1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_SURCHARGE = 0.10;
11	
12	const BASE_PREMIUM: Record<string, number> = {
13	  sword: 100,
14	  amulet: 60,
15	};
16	
17	const roundUp = (n: number): number => Math.ceil(n - 1e-9);
18	
19	const computePremium = (items: Item[]): number => {
20	  if (items.length === 0) return PROCESSING_FEE;
21	  const itemBase = items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
22	  return roundUp(itemBase * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
23	};
24	
25	export const runScenario = (scenario: Scenario): ScenarioResult => ({
26	  results: scenario.steps.map((step) => ({ premium: computePremium(step.items) })),
27	});
28

